package at.hausgarten.service;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

/** Synthetic evidence only; no activity launch, external account, production import or actual cutover. */
final class LocalAuthorityEvidenceNativeAcceptance {
    private static JSONObject ledger()throws Exception {return new JSONObject().put("formatVersion",1).put("last_number",17).put("external_writers_disabled",false).put("checked_at","2026-10-24T00:00:00Z").put("issued",new JSONArray().put(new JSONObject().put("invoice_id","qa_external_invoice").put("invoice_number","QA-2026-0017").put("pdf_sha256",PixelMcpWriteTools.hash("qa_external_original")).put("pdf_byte_size",128))).put("reservations",new JSONArray().put(new JSONObject().put("reservation_id","qa_cancelled_reservation").put("invoice_id","qa_cancelled_invoice").put("invoice_number","QA-2026-0016").put("counter",16).put("state","cancelled"))).put("opening_balances",new JSONArray().put(new JSONObject().put("invoice_id","qa_external_invoice").put("remaining_minor",8800)));}
    private static void refused(PixelMcpInstrumentation.Task task)throws Exception {try{task.run();}catch(IOException|JSONException expected){return;}throw new AssertionError("Malformed external evidence was accepted");}
    static void run(PixelMcpInstrumentation test)throws Exception {
        test.probe("manual authority evidence hashes exact UTF8 source and rejects incomplete duplicate or floating number proofs",()->{
            JSONObject source=ledger();String original=source.toString();byte[] bytes=original.getBytes(StandardCharsets.UTF_8);LocalAuthorityEvidence.Loaded loaded=LocalAuthorityEvidence.parse(new ByteArrayInputStream(bytes));JSONObject result=loaded.ledger("2026-10-24T01:00:00Z");test.yes(loaded.sha256.equals(PhotoAttachmentStore.sha256(bytes))&&result.getString("evidence_reference").equals("sha256:"+loaded.sha256)&&result.getString("checked_at").equals("2026-10-24T01:00:00Z")&&result.getBoolean("external_writers_disabled"));test.yes(source.toString().equals(original)&&!source.getBoolean("external_writers_disabled")&&loaded.summary().getInt("issued_count")==1&&result.getJSONArray("opening_balances").getJSONObject(0).getLong("remaining_minor")==8800);
            String now=java.time.Instant.now().toString();JSONObject authority=new JSONObject().put("installation_id","qa_replacement_installation").put("restore_epoch","qa_after_restore_epoch").put("blocked_at",java.time.Instant.now().minusSeconds(2).toString());test.yes(!result.has("current_review"));refused(()->loaded.reviewedLedger(now,authority,false));JSONObject currentReview=loaded.reviewedLedger(now,authority,true).getJSONObject("current_review");test.yes(currentReview.getBoolean("confirmed")&&currentReview.getString("installation_id").equals("qa_replacement_installation")&&currentReview.getString("restore_epoch").equals("qa_after_restore_epoch")&&currentReview.getString("evidence_sha256").equals(loaded.sha256));refused(()->loaded.reviewedLedger("2026-10-24T00:00:00Z",new JSONObject(authority.toString()).put("blocked_at","2026-10-24T01:00:00Z"),true));
            refused(()->LocalAuthorityEvidence.normalizeLedger(new JSONObject(original).put("last_number",17.5)));JSONObject duplicate=new JSONObject(original);duplicate.getJSONArray("issued").put(new JSONObject(duplicate.getJSONArray("issued").getJSONObject(0).toString()));refused(()->LocalAuthorityEvidence.normalizeLedger(duplicate));JSONObject badReservation=new JSONObject(original);badReservation.getJSONArray("reservations").getJSONObject(0).put("counter",18);refused(()->LocalAuthorityEvidence.normalizeLedger(badReservation));JSONObject wrongBalance=new JSONObject(original);wrongBalance.getJSONArray("opening_balances").getJSONObject(0).put("invoice_id","qa_unproven_invoice");refused(()->LocalAuthorityEvidence.normalizeLedger(wrongBalance));refused(()->LocalAuthorityEvidence.parse(new ByteArrayInputStream((original+" false").getBytes(StandardCharsets.UTF_8))));refused(()->LocalAuthorityEvidence.parse(new ByteArrayInputStream(new byte[]{(byte)0xc3,(byte)0x28})));
            InputStream tooLarge=new InputStream(){int remaining=LocalAuthorityEvidence.MAX_JSON_BYTES+1;public int read(){return remaining-->0?' ': -1;}public int read(byte[] target,int offset,int length){if(remaining<=0)return -1;int count=Math.min(length,remaining);java.util.Arrays.fill(target,offset,offset+count,(byte)' ');remaining-=count;return count;}};refused(()->LocalAuthorityEvidence.parse(tooLarge));
        });
        test.probe("manual PDF recovery evidence preserves frozen binding and requires a fresh explicit never-created review",()->{
            JSONObject source=ledger(),row=source.getJSONArray("issued").getJSONObject(0);String frozen=PixelMcpWriteTools.hash("qa_frozen_pending_pdf");row.put("snapshot_sha256",frozen);JSONObject original=LocalAuthorityEvidence.normalizeLedger(source).getJSONArray("issued").getJSONObject(0);test.yes(original.getString("pdf_resolution").equals("original")&&original.getString("snapshot_sha256").equals(frozen)&&original.getLong("pdf_byte_size")==128);
            row.remove("pdf_sha256");row.remove("pdf_byte_size");row.put("pdf_resolution","not_created").put("not_created_confirmed",true).put("not_created_reason","QA current external proof: document was never produced");LocalAuthorityEvidence.Loaded loaded=LocalAuthorityEvidence.parse(new ByteArrayInputStream(source.toString().getBytes(StandardCharsets.UTF_8)));JSONObject summary=loaded.summary();test.yes(summary.getBoolean("ledger_valid")&&summary.getInt("pending_not_created_count")==1&&summary.getInt("original_reference_count")==0&&summary.getInt("unresolved_pdf_count")==0);JSONObject authority=new JSONObject().put("installation_id","qa_pdf_replacement").put("restore_epoch","qa_pdf_new_epoch");String now=java.time.Instant.now().toString();refused(()->loaded.reviewedLedger(now,authority,true));refused(()->loaded.reviewedLedger(now,authority,true,false));JSONObject confirmed=loaded.reviewedLedger(now,authority,true,true).getJSONArray("issued").getJSONObject(0);test.yes(confirmed.getString("snapshot_sha256").equals(frozen)&&confirmed.getBoolean("not_created_confirmed")&&!confirmed.has("pdf_sha256")&&!confirmed.has("pdf_byte_size"));JSONObject missingBinding=new JSONObject(source.toString());missingBinding.getJSONArray("issued").getJSONObject(0).remove("snapshot_sha256");refused(()->LocalAuthorityEvidence.normalizeLedger(missingBinding));JSONObject falseOriginal=new JSONObject(source.toString());falseOriginal.getJSONArray("issued").getJSONObject(0).put("pdf_sha256",PixelMcpWriteTools.hash("qa_some_existing_pdf"));refused(()->LocalAuthorityEvidence.normalizeLedger(falseOriginal));JSONObject unknown=new JSONObject(source.toString());unknown.getJSONArray("issued").getJSONObject(0).put("pdf_resolution","unknown");LocalAuthorityEvidence.Loaded unresolved=LocalAuthorityEvidence.parse(new ByteArrayInputStream(unknown.toString().getBytes(StandardCharsets.UTF_8)));test.yes(!unresolved.summary().getBoolean("ledger_valid")&&unresolved.summary().getInt("unresolved_pdf_count")==1);
        });
        test.probe("manual authority request survives screen recreation with frozen request ID and cannot revive after restore epoch change",()->{try(OwnerNativeAcceptance.Fixture fixture=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            String before=PixelMcpWriteTools.hash(fixture.store.getState().getJSONObject("master"));JSONObject body=new JSONObject().put("request_id","qa_manual_authority_request").put("expected_preview_hash",PixelMcpWriteTools.hash("qa_preview")).put("backup_id","qa_verified_backup").put("writer_evidence",new JSONObject().put("formatVersion",1).put("external_writers_disabled",true).put("evidence_sha256",PixelMcpWriteTools.hash("qa_evidence")).put("evidence_reference","qa_selected_evidence").put("checked_at","2026-10-24T01:00:00Z"));String frozen=body.toString();
            LocalAuthorityEvidence.savePending(fixture.context,"activate_local_authority",frozen,"content://qa.synthetic/evidence",PixelMcpWriteTools.hash("qa_evidence"),"qa_verified_backup");JSONObject reopened=LocalAuthorityEvidence.loadPending(fixture.context);test.yes(reopened.getString("pending_body").equals(frozen)&&reopened.getString("pending_name").equals("activate_local_authority"));LocalAuthorityEvidence.clearPending(fixture.context,"qa_not_the_frozen_body");test.yes(LocalAuthorityEvidence.loadPending(fixture.context).getString("pending_body").equals(frozen));
            BackupDeviceGuard guard=new BackupDeviceGuard(fixture.context);guard.advanceForRestore("qa_authority_ui_restore",guard.current().getString("restoreEpoch"));JSONObject stale=LocalAuthorityEvidence.loadPending(fixture.context);test.yes(stale.getBoolean("stale_context")&&!stale.has("pending_body")&&before.equals(PixelMcpWriteTools.hash(fixture.store.getState().getJSONObject("master"))));
        }});
    }
    private LocalAuthorityEvidenceNativeAcceptance(){}
}
